def compute_growth_exponent(count: int, n: int) -> float:
    if n <= 0 or count <= 0:
        return 0.0
    return math.log(count) / (n * math.log(2))

def refine_spectral_bounds(growth, max_n):
    exponents = [growth.growth_exponent(n) for n in range(1, max_n + 1)]
    return min(exponents), max(exponents)

def approximate_dimension_from_below(n: int, k: int) -> float:
    if n <= 0 or k <= 0:
        return 0.0
    return math.log(k) / (n * math.log(2))
